#!/usr/bin/env python3
"""Graph update for 2026-07-19 evening brief.

Applies signals, price/current updates, summary refreshes, trigger decisions
and edge weight changes derived from:
  staging/2026-07-19-evening/intel.md
  staging/2026-07-19-evening/markets.md

Backup: backups/2026-07-19/graph_v1
"""
import json, os, sys

D = "2026-07-19"
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
NODES = os.path.join(ROOT, "graph", "nodes")

log = []


def load(nid):
    p = os.path.join(NODES, nid + ".json")
    if not os.path.exists(p):
        log.append(("MISSING", nid))
        return None, None
    with open(p) as f:
        return json.load(f), p


def save(d, p):
    with open(p, "w") as f:
        json.dump(d, f, indent=1, ensure_ascii=False)


def sig(nid, headline):
    d, p = load(nid)
    if d is None:
        return
    d.setdefault("recent_signals", []).append({"date": D, "headline": headline})
    d["last_updated"] = D
    save(d, p)
    log.append(("SIGNAL", nid))


def current(nid, **kw):
    d, p = load(nid)
    if d is None:
        return
    d.setdefault("current", {}).update(kw)
    d["last_updated"] = D
    save(d, p)
    log.append(("CURRENT", nid))


def summary(nid, text):
    d, p = load(nid)
    if d is None:
        return
    d["summary"] = text
    d["last_updated"] = D
    save(d, p)
    log.append(("SUMMARY", nid))


def snapshot(nid, price, trigger):
    d, p = load(nid)
    if d is None:
        return
    d.setdefault("price_snapshots", []).append(
        {"date": D, "price": price, "trigger": trigger})
    d["last_updated"] = D
    save(d, p)
    log.append(("SNAPSHOT", nid))


def trig_set(nid, match, status, note=None):
    """Change status of an existing trigger whose condition contains `match`."""
    d, p = load(nid)
    if d is None:
        return
    hit = False
    for t in d.get("active_triggers", []):
        if match.lower() in str(t.get("condition", "")).lower():
            t["status"] = status
            t["status_changed"] = D
            if note:
                t["notes"] = note
            hit = True
            break
    if hit:
        d["last_updated"] = D
        save(d, p)
        log.append(("TRIGGER", nid, status))
    else:
        log.append(("TRIGGER-NOTFOUND", nid, match))


def trig_add(nid, condition, status, cascade, note):
    d, p = load(nid)
    if d is None:
        return
    d.setdefault("active_triggers", []).append({
        "condition": condition, "status": status,
        "cascade": cascade, "added": D, "notes": note})
    d["last_updated"] = D
    save(d, p)
    log.append(("TRIGGER-NEW", nid))


